CREATE TABLE "GoogleReview" (
  "id" TEXT NOT NULL,
  "sourceId" TEXT NOT NULL,
  "author" TEXT NOT NULL,
  "rating" INTEGER NOT NULL CHECK ("rating" BETWEEN 1 AND 5),
  "originalText" TEXT NOT NULL DEFAULT '',
  "excerpt" TEXT NOT NULL DEFAULT '',
  "categories" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],
  "sourceUrl" TEXT NOT NULL,
  "reviewedAt" TIMESTAMP(3),
  "published" BOOLEAN NOT NULL DEFAULT true,
  "featured" BOOLEAN NOT NULL DEFAULT false,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "GoogleReview_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "GoogleReview_sourceId_key" ON "GoogleReview"("sourceId");
CREATE INDEX "GoogleReview_published_rating_idx" ON "GoogleReview"("published", "rating");

-- Initial selected passages from published five-star reviews. Future edits live in PostgreSQL.
